-- ===== 0001_initial_schema.sql =====
-- ORBIT initial schema. Mirrors src/database/migrations (SQLite). Student-owned rows are RLS-protected.
create extension if not exists "pgcrypto";

create type verification_status as enum ('draft','extracted','needs_review','verified','published','archived');

-- Ownership helper: every student-owned row carries owner_id = auth.uid().
create table profiles (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,
  display_name text not null,
  class_level int not null,
  academic_year text not null,
  board text, institution text, programme text,
  preferred_language text not null default 'en' check (preferred_language in ('en','te')),
  weekday_study_minutes int not null default 120,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz,
  unique (owner_id)
);

create table subjects (
  id uuid primary key default gen_random_uuid(),
  key text not null unique check (key in ('math','physics','chemistry')),
  name text not null, sort_order int not null default 0,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);

create table content_sources (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid default auth.uid() references auth.users(id),
  title text not null,
  source_type text not null check (source_type in ('coaching_notes','textbook','reference_book','question_paper','answer_key','original','ai_generated','student')),
  location text, imported_at timestamptz, reviewer text,
  verification_status verification_status not null default 'draft',
  content_version int not null default 1,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);

create table chapters (
  id uuid primary key default gen_random_uuid(),
  subject_id uuid not null references subjects(id),
  title text not null, sort_order int not null default 0,
  source_id uuid references content_sources(id),
  verification_status verification_status not null default 'draft',
  content_version int not null default 1,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table topics (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid default auth.uid() references auth.users(id),
  chapter_id uuid not null references chapters(id),
  parent_topic_id uuid references topics(id),
  title text not null, sort_order int not null default 0,
  status text not null default 'not_started'
    check (status in ('not_started','learning','learning_completed','practising','needs_revision','mastered')),
  source_id uuid references content_sources(id),
  verification_status verification_status not null default 'draft',
  content_version int not null default 1,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz
);
create table learning_content (
  id uuid primary key default gen_random_uuid(),
  chapter_id uuid not null references chapters(id), topic_id uuid references topics(id),
  section text not null, language text not null default 'en' check (language in ('en','te')),
  level text not null default 'main' check (level in ('foundation','main','advanced')),
  body text not null, sort_order int not null default 0,
  source_id uuid references content_sources(id),
  verification_status verification_status not null default 'draft',
  content_version int not null default 1,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table formulas (
  id uuid primary key default gen_random_uuid(),
  chapter_id uuid not null references chapters(id), topic_id uuid references topics(id),
  name text not null, latex text not null, variables jsonb not null default '[]',
  units text, conditions text, explanation text, example text,
  source_id uuid references content_sources(id),
  verification_status verification_status not null default 'draft',
  content_version int not null default 1,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table questions (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid default auth.uid() references auth.users(id),
  chapter_id uuid not null references chapters(id), topic_id uuid references topics(id),
  type text not null check (type in ('single','multi','integer','matching','assertion_reason')),
  stem text not null, options jsonb, image_path text,
  difficulty text not null default 'main' check (difficulty in ('foundation','main','advanced')),
  origin text not null default 'student' check (origin in ('official','coaching','generated','student')),
  generation jsonb,
  source_id uuid references content_sources(id),
  verification_status verification_status not null default 'draft',
  content_version int not null default 1,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz
);
-- Answer keys are separate and only reachable through the service-role edge function / verified-published view.
create table question_solutions (
  id uuid primary key default gen_random_uuid(),
  question_id uuid not null unique references questions(id) on delete cascade,
  answer jsonb not null, explanation text, hint text,
  source_id uuid references content_sources(id),
  verification_status verification_status not null default 'draft',
  content_version int not null default 1,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);

create table exam_templates (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null default auth.uid() references auth.users(id),
  name text not null, style text not null check (style in ('main','advanced')),
  duration_minutes int, negative_marking_enabled boolean not null default true,
  source_note text, verification_status verification_status not null default 'needs_review',
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table exam_sections (
  id uuid primary key default gen_random_uuid(),
  template_id uuid not null references exam_templates(id) on delete cascade,
  section_key text not null, name text not null, subject_key text not null, question_type text not null,
  question_count int not null check (question_count > 0), attempt_limit int, sort_order int not null default 0,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (template_id, section_key)
);
create table scoring_rules (
  id uuid primary key default gen_random_uuid(),
  section_id uuid not null unique references exam_sections(id) on delete cascade,
  correct numeric not null check (correct >= 0),
  incorrect numeric not null check (incorrect <= 0),
  unanswered numeric not null default 0,
  partial_per_correct_option numeric,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table exams (
  id uuid primary key,
  owner_id uuid not null default auth.uid() references auth.users(id),
  template_id uuid references exam_templates(id),
  name text not null, style text not null check (style in ('main','advanced')),
  exam_date date not null, syllabus jsonb not null default '[]',
  status text not null default 'scheduled' check (status in ('scheduled','in_progress','completed')),
  entry_mode text not null default 'engine' check (entry_mode in ('engine','manual')),
  started_at timestamptz, finished_at timestamptz, total_score numeric, max_score numeric,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz
);
create table exam_subject_results (
  id uuid primary key,
  owner_id uuid not null default auth.uid() references auth.users(id),
  exam_id uuid not null references exams(id) on delete cascade,
  subject_key text not null, marks numeric not null, max_marks numeric not null,
  correct int, incorrect int, unanswered int, negative_lost numeric,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (exam_id, subject_key)
);
create table question_attempts (
  id uuid primary key,
  owner_id uuid not null default auth.uid() references auth.users(id),
  question_id uuid references questions(id), exam_id uuid references exams(id),
  kind text not null default 'practice' check (kind in ('concept_check','practice','revision','exam')),
  selected jsonb, numeric_answer numeric,
  outcome text not null check (outcome in ('correct','partial','incorrect','unanswered')),
  marks numeric not null default 0, time_ms int not null default 0,
  hint_used boolean not null default false, marked_for_review boolean not null default false,
  attempted_at timestamptz not null,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz
);
create table study_tasks (
  id uuid primary key,
  owner_id uuid not null default auth.uid() references auth.users(id),
  plan_date date not null, slot text not null, title text not null, detail text,
  subject_key text, chapter_id uuid, topic_id uuid, planned_minutes int not null,
  status text not null default 'pending' check (status in ('pending','done','skipped','rescheduled')),
  completed_at timestamptz,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz,
  unique (owner_id, plan_date, slot)
);
create table study_sessions (
  id uuid primary key,
  owner_id uuid not null default auth.uid() references auth.users(id),
  task_id uuid references study_tasks(id), subject_key text, chapter_id uuid,
  started_at timestamptz not null, ended_at timestamptz, actual_minutes int not null default 0,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz
);
create table mistake_entries (
  id uuid primary key,
  owner_id uuid not null default auth.uid() references auth.users(id),
  subject_key text not null, chapter_id uuid references chapters(id), topic_id uuid references topics(id), question_id uuid references questions(id),
  question_text text not null, image_path text,
  my_answer text, correct_answer text, official_explanation text, working_steps text, student_note text,
  category text not null check (category in ('conceptual','approach','calculation','formula_misuse','careless','time_management','misread')),
  ocr_confirmed boolean not null default true,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz
);
create table revision_schedule (
  id uuid primary key,
  owner_id uuid not null default auth.uid() references auth.users(id),
  mistake_id uuid not null unique references mistake_entries(id) on delete cascade,
  stage int not null default 0, interval_days int not null default 1, consecutive_wrong int not null default 0,
  due_on date not null, last_reviewed_at timestamptz, review_concept boolean not null default false,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz
);
create table topic_mastery (
  id uuid primary key,
  owner_id uuid not null default auth.uid() references auth.users(id),
  topic_id uuid references topics(id), chapter_id uuid not null references chapters(id),
  score numeric, confidence text, evidence_count int not null default 0, weakest_component text, last_assessed_at timestamptz,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz,
  unique (owner_id, chapter_id, topic_id)
);
create table ai_conversations (
  id uuid primary key,
  owner_id uuid not null default auth.uid() references auth.users(id),
  chapter_id uuid references chapters(id), topic_id uuid references topics(id), title text, language text not null default 'en',
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz
);
create table ai_messages (
  id uuid primary key,
  owner_id uuid not null default auth.uid() references auth.users(id),
  conversation_id uuid not null references ai_conversations(id) on delete cascade,
  role text not null check (role in ('user','assistant','system')), body text not null, meta jsonb,
  saved_to_notes boolean not null default false,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz
);
create table notes (
  id uuid primary key,
  owner_id uuid not null default auth.uid() references auth.users(id),
  chapter_id uuid references chapters(id), topic_id uuid references topics(id),
  title text, body text not null, source text not null default 'student',
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz
);

create index on chapters(subject_id);
create index on topics(chapter_id);
create index on learning_content(chapter_id, topic_id);
create index on formulas(chapter_id);
create index on questions(chapter_id, difficulty);
create index on question_attempts(owner_id, attempted_at);
create index on question_attempts(question_id);
create index on study_tasks(owner_id, plan_date);
create index on mistake_entries(owner_id, chapter_id);
create index on revision_schedule(owner_id, due_on);
create index on ai_messages(conversation_id);

-- Keep updated_at honest and make sync conflict detection possible (server wins only if strictly newer).
create function touch_updated_at() returns trigger language plpgsql as $$
begin
  if tg_op = 'UPDATE' and new.updated_at is not distinct from old.updated_at then new.updated_at = now(); end if;
  return new;
end $$;
do $$ declare t text; begin
  foreach t in array array['profiles','subjects','chapters','topics','learning_content','formulas','questions','question_solutions',
    'exam_templates','exam_sections','scoring_rules','exams','exam_subject_results','question_attempts','study_tasks','study_sessions',
    'mistake_entries','revision_schedule','topic_mastery','ai_conversations','ai_messages','notes','content_sources'] loop
    execute format('create trigger %I before update on %I for each row execute function touch_updated_at()', 'touch_'||t, t);
  end loop;
end $$;

-- ===== 0002_row_level_security.sql =====
-- Row Level Security. Default deny; anon gets nothing.
do $$ declare t text; begin
  foreach t in array array[
    'profiles','topics','questions','exam_templates','exams','exam_subject_results','question_attempts','study_tasks','study_sessions',
    'mistake_entries','revision_schedule','topic_mastery','ai_conversations','ai_messages','notes','content_sources'] loop
    execute format('alter table %I enable row level security', t);
    execute format('create policy %I on %I for all to authenticated using (owner_id = auth.uid()) with check (owner_id = auth.uid())', t||'_owner', t);
  end loop;
end $$;

-- Shared reference tables: readable by signed-in students, writable only via service role (no write policy).
alter table subjects enable row level security;
alter table chapters enable row level security;
alter table learning_content enable row level security;
alter table formulas enable row level security;
alter table exam_sections enable row level security;
alter table scoring_rules enable row level security;
alter table question_solutions enable row level security;
create policy subjects_read on subjects for select to authenticated using (true);
create policy chapters_read on chapters for select to authenticated using (true);
create policy learning_read on learning_content for select to authenticated
  using (verification_status in ('verified','published'));
create policy formulas_read on formulas for select to authenticated
  using (verification_status in ('verified','published'));
create policy sections_read on exam_sections for select to authenticated
  using (exists (select 1 from exam_templates t where t.id = template_id and t.owner_id = auth.uid()));
create policy sections_write on exam_sections for all to authenticated
  using (exists (select 1 from exam_templates t where t.id = template_id and t.owner_id = auth.uid()))
  with check (exists (select 1 from exam_templates t where t.id = template_id and t.owner_id = auth.uid()));
create policy rules_all on scoring_rules for all to authenticated
  using (exists (select 1 from exam_sections s join exam_templates t on t.id = s.template_id where s.id = section_id and t.owner_id = auth.uid()))
  with check (exists (select 1 from exam_sections s join exam_templates t on t.id = s.template_id where s.id = section_id and t.owner_id = auth.uid()));

-- question_solutions has NO policy for authenticated: answer keys are served only by edge functions
-- (service role) after an attempt is submitted, so list queries can never leak them.

-- Students may only insert questions as their own, never as verified/published.
create policy questions_no_self_verify on questions as restrictive for insert to authenticated
  with check (verification_status in ('draft','extracted','needs_review'));
create policy questions_no_self_verify_upd on questions as restrictive for update to authenticated
  with check (verification_status in ('draft','extracted','needs_review'));

revoke all on all tables in schema public from anon;

-- Verified/published questions form the shared bank; students always see their own as well.
create policy questions_read_verified on questions for select to authenticated
  using (verification_status in ('verified','published'));

-- ===== 0003_questions_owner_mock_attempts.sql =====
alter table questions add column if not exists source_note text;

-- Student-entered answer keys belong to the student; shared-bank keys (owner_id null) stay unreadable by clients.
alter table question_solutions add column if not exists owner_id uuid default auth.uid() references auth.users(id);
create policy solutions_owner on question_solutions for all to authenticated
  using (owner_id = auth.uid()) with check (owner_id = auth.uid());
create policy solutions_no_self_verify on question_solutions as restrictive for insert to authenticated
  with check (verification_status in ('draft','extracted','needs_review','verified'));

create table mock_attempts (
  id uuid primary key,
  owner_id uuid not null default auth.uid() references auth.users(id),
  name text not null, config jsonb not null,
  started_at timestamptz not null, finished_at timestamptz not null,
  total_marks numeric not null, max_marks numeric not null,
  percentage numeric not null, accuracy numeric not null, attempt_rate numeric not null,
  negative_lost numeric not null default 0, duration_ms int not null default 0, result jsonb not null,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz
);
create index on mock_attempts(owner_id, finished_at);
alter table mock_attempts enable row level security;
create policy mock_attempts_owner on mock_attempts for all to authenticated using (owner_id = auth.uid()) with check (owner_id = auth.uid());
create trigger touch_mock_attempts before update on mock_attempts for each row execute function touch_updated_at();

-- ===== 0004_student_verified_questions.sql =====
-- Students confirm their own answer keys, so they may save questions as 'verified' (never 'published',
-- which stays admin-only), but a generated (AI) question can never be marked verified by the client.
drop policy if exists questions_no_self_verify on questions;
drop policy if exists questions_no_self_verify_upd on questions;
create policy questions_self_verify_ins on questions as restrictive for insert to authenticated
  with check (verification_status in ('draft','extracted','needs_review','verified')
              and not (origin = 'generated' and verification_status = 'verified'));
create policy questions_self_verify_upd on questions as restrictive for update to authenticated
  with check (verification_status in ('draft','extracted','needs_review','verified')
              and not (origin = 'generated' and verification_status = 'verified'));

drop policy if exists solutions_no_self_verify on question_solutions;
create policy solutions_self_verify on question_solutions as restrictive for insert to authenticated
  with check (verification_status in ('draft','extracted','needs_review','verified'));

-- The sync engine pulls with `updated_at >= cursor ORDER BY updated_at`; index it on every synced table.
do $$ declare t text; begin
  foreach t in array array['profiles','exam_templates','exams','topics','questions','question_solutions','exam_subject_results','question_attempts',
    'mock_attempts','study_tasks','study_sessions','mistake_entries','revision_schedule','topic_mastery','ai_conversations','ai_messages','notes'] loop
    execute format('create index if not exists %I on %I (owner_id, updated_at)', t||'_owner_updated_idx', t);
  end loop;
end $$;

-- ===== 0005_harden_privileges.sql =====
-- Hardening found by running the migrations against a real Postgres (tests/live/rls.test.ts).
-- Row-level security does NOT cover TRUNCATE, and Supabase's default privileges grant it to API roles, so revoke it explicitly.

-- 1. Signed-out visitors get nothing, including on tables created after migration 0002.
revoke all on all tables in schema public from anon;
revoke all on all sequences in schema public from anon;
alter default privileges in schema public revoke all on tables from anon;
alter default privileges in schema public revoke all on sequences from anon;

-- 2. Signed-in students may read and write rows (RLS decides which), but never TRUNCATE or alter table-level behaviour.
revoke truncate, references, trigger on all tables in schema public from authenticated;
alter default privileges in schema public revoke truncate, references, trigger on tables from authenticated;

-- 3. Shared reference tables are read-only for students (no write policy existed, but remove the privilege too).
revoke insert, update, delete on subjects, chapters, learning_content, formulas from authenticated;

-- 4. The shared question bank is for questions with no owner. A student's own verified question must stay private to them.
drop policy if exists questions_read_verified on questions;
create policy questions_read_shared on questions for select to authenticated
  using (owner_id is null and verification_status in ('verified','published'));

-- ===== 0006_sync_columns.sql =====
-- Found by tests/live/sync.live.test.ts "schema contract": the app writes `deleted_at` on every table,
-- but these server tables lacked it, so every upload of them was rejected.
alter table exam_templates       add column if not exists deleted_at timestamptz;
alter table exam_sections        add column if not exists deleted_at timestamptz;
alter table scoring_rules        add column if not exists deleted_at timestamptz;
alter table question_solutions   add column if not exists deleted_at timestamptz;
alter table exam_subject_results add column if not exists deleted_at timestamptz;

-- ===== 0007_student_authored_content.sql =====
-- Students can write their own lessons and formulas (from their books), and these sync between their devices.
-- Shared rows (owner_id null) stay read-only; a student can never publish, only save as draft / needs_review / verified.
alter table learning_content add column if not exists owner_id uuid default auth.uid() references auth.users(id);
alter table learning_content add column if not exists deleted_at timestamptz;
alter table learning_content add column if not exists source_note text;
alter table formulas add column if not exists owner_id uuid default auth.uid() references auth.users(id);
alter table formulas add column if not exists deleted_at timestamptz;
alter table formulas add column if not exists source_note text;

drop policy if exists learning_read on learning_content;
drop policy if exists formulas_read on formulas;
create policy learning_read on learning_content for select to authenticated
  using ((owner_id is null and verification_status in ('verified','published')) or owner_id = auth.uid());
create policy formulas_read on formulas for select to authenticated
  using ((owner_id is null and verification_status in ('verified','published')) or owner_id = auth.uid());

create policy learning_owner_write on learning_content for all to authenticated
  using (owner_id = auth.uid())
  with check (owner_id = auth.uid() and verification_status in ('draft','extracted','needs_review','verified'));
create policy formulas_owner_write on formulas for all to authenticated
  using (owner_id = auth.uid())
  with check (owner_id = auth.uid() and verification_status in ('draft','extracted','needs_review','verified'));

-- Migration 0005 removed write privileges from these two tables; restore them (RLS above decides which rows).
grant insert, update, delete on learning_content, formulas to authenticated;

create index if not exists learning_content_owner_updated_idx on learning_content (owner_id, updated_at);
create index if not exists formulas_owner_updated_idx on formulas (owner_id, updated_at);

-- ===== 0008_persistent_daily_plan.sql =====
-- Daily plan tasks are stored (one row per day and slot) so they can be completed, timed and synced.
alter table study_tasks add column if not exists start_time text;
alter table study_tasks add column if not exists end_time text;
alter table study_tasks add column if not exists difficulty text;
alter table study_tasks add column if not exists external boolean not null default false;
alter table study_tasks add column if not exists needs_setup text;
